<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Image Preview</title>
  <script src="https://unpkg.com/react@18/umd/react.production.min.js" crossorigin></script>
  <script src="https://unpkg.com/react-dom@18/umd/react-dom.production.min.js" crossorigin></script>
  <script src="https://unpkg.com/babel-standalone@6/babel.min.js"></script>
  <style>
    :root {
      --bg-color: #121212;
      --container-bg: #1e1e1e;
      --text-color: #e0e0e0;
      --border-color: #444;
      --primary-color: #bb86fc;
      --danger-color: #cf6679;
      --danger-hover: #ff7597;
      --btn-hover-bg: rgba(255, 255, 255, 0.08);
    }

    body {
      background-color: var(--bg-color);
      color: var(--text-color);
      font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
      margin: 0;
      display: flex;
      justify-content: center;
      align-items: center;
      min-height: 100vh;
      padding: 16px;
      box-sizing: border-box;
    }

    .image-preview-container {
      max-width: 600px;
      width: 100%;
      padding: 24px;
      background-color: var(--container-bg);
      border-radius: 12px;
      box-shadow: 0 8px 24px rgba(0,0,0,0.5);
      display: flex;
      flex-direction: column;
      align-items: center;
    }

    .image-preview-container img {
      max-width: 100%;
      height: auto;
      border-radius: 8px;
      margin-bottom: 24px;
      border: 1px solid var(--border-color);
    }

    button {
      padding: 10px 20px;
      border: none;
      border-radius: 6px;
      font-size: 1rem;
      font-weight: 500;
      cursor: pointer;
      transition: background-color 0.2s, color 0.2s;
    }

    button:focus-visible {
      outline: 2px solid var(--primary-color);
      outline-offset: 2px;
    }

    button.trigger {
      background-color: transparent;
      color: var(--danger-color);
      border: 1px solid var(--danger-color);
    }

    button.trigger:hover {
      background-color: rgba(207, 102, 121, 0.1);
    }

    dialog {
      background-color: var(--container-bg);
      color: var(--text-color);
      border: 1px solid var(--border-color);
      border-radius: 12px;
      padding: 24px;
      max-width: 400px;
      width: 100%;
      box-shadow: 0 16px 32px rgba(0,0,0,0.8);
    }

    dialog::backdrop {
      background-color: rgba(0, 0, 0, 0.75);
      backdrop-filter: blur(2px);
    }

    dialog h2 {
      margin-top: 0;
      margin-bottom: 16px;
      font-size: 1.25rem;
      font-weight: 600;
    }

    dialog p {
      margin-top: 0;
      margin-bottom: 32px;
      line-height: 1.5;
      color: #b0b0b0;
    }

    .dialog-actions {
      display: flex;
      justify-content: flex-end;
      gap: 12px;
    }

    .btn-cancel {
      background-color: transparent;
      color: var(--text-color);
      border: 1px solid var(--border-color);
    }

    .btn-cancel:hover {
      background-color: var(--btn-hover-bg);
    }

    .btn-delete {
      background-color: var(--danger-color);
      color: #000;
    }

    .btn-delete:hover {
      background-color: var(--danger-hover);
    }

    .status-message {
      font-size: 1.125rem;
      color: var(--text-color);
      text-align: center;
    }
  </style>
</head>
<body>
  <div id="root"></div>

  <script type="text/babel">
    const { useState, useRef, useEffect } = React;

    function Modal({ isOpen, onClose, onConfirm }) {
      const dialogRef = useRef(null);

      useEffect(() => {
        const dialog = dialogRef.current;
        if (isOpen && dialog && !dialog.open) {
          dialog.showModal();
        } else if (!isOpen && dialog && dialog.open) {
          dialog.close();
        }
      }, [isOpen]);

      useEffect(() => {
        const dialog = dialogRef.current;
        const handleCancel = (e) => {
          e.preventDefault();
          onClose();
        };
        if (dialog) {
          dialog.addEventListener('cancel', handleCancel);
          return () => dialog.removeEventListener('cancel', handleCancel);
        }
      }, [onClose]);

      return (
        <dialog 
          ref={dialogRef} 
          aria-labelledby="confirm-heading"
          aria-describedby="confirm-body"
        >
          <h2 id="confirm-heading">Delete Image?</h2>
          <p id="confirm-body">Are you sure you want to delete this image from your library? This action cannot be undone.</p>
          <div className="dialog-actions">
            <button 
              type="button" 
              className="btn-cancel" 
              onClick={onClose}
              autoFocus
            >
              Cancel
            </button>
            <button 
              type="button" 
              className="btn-delete" 
              onClick={onConfirm}
            >
              Delete
            </button>
          </div>
        </dialog>
      );
    }

    function ImagePreview() {
      const [isModalOpen, setIsModalOpen] = useState(false);
      const [isDeleted, setIsDeleted] = useState(false);
      const deletedMessageRef = useRef(null);

      useEffect(() => {
        if (isDeleted && deletedMessageRef.current) {
          deletedMessageRef.current.focus();
        }
      }, [isDeleted]);

      const handleDeleteClick = () => {
        setIsModalOpen(true);
      };

      const handleCloseModal = () => {
        setIsModalOpen(false);
      };

      const handleConfirmDelete = () => {
        setIsModalOpen(false);
        setIsDeleted(true);
      };

      if (isDeleted) {
        return (
          <div className="image-preview-container">
            <p 
              className="status-message"
              ref={deletedMessageRef}
              tabIndex="-1" 
              role="status"
              style={{ outline: 'none' }}
            >
              Image successfully deleted.
            </p>
          </div>
        );
      }

      return (
        <main className="image-preview-container">
          <h1>Image Preview</h1>
          <img 
            src="https://placehold.co/600x400/2c2c2c/e0e0e0?text=Landscape+Photograph" 
            alt="Landscape photograph" 
            width="600"
            height="400"
          />
          <div>
            <button 
              type="button" 
              className="trigger" 
              onClick={handleDeleteClick}
            >
              Delete Image
            </button>
          </div>

          <Modal 
            isOpen={isModalOpen} 
            onClose={handleCloseModal} 
            onConfirm={handleConfirmDelete} 
          />
        </main>
      );
    }

    const root = ReactDOM.createRoot(document.getElementById('root'));
    root.render(<ImagePreview />);
  </script>
</body>
